 altera IG ni activa funcionalidades.","efecto":"BLOQUEAR","autoridad":"LEG-PRODUCTO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/622","solicitante":"Cristhian / Claude S21 2026-11-24"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s21c08_modulo_auth"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"s21c08_exclusion_invalida"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s21c08_cambio_sin_revalidar"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"Vector 1","entrada":{"s21c08_modulo_auth":false,"s21c08_exclusion_invalida":false,"s21c08_cambio_sin_revalidar":false},"esperado":false},{"casuistica":"Vector 2","entrada":{"s21c08_modulo_auth":false,"s21c08_exclusion_invalida":false,"s21c08_cambio_sin_revalidar":true},"esperado":false},{"casuistica":"Vector 3","entrada":{"s21c08_modulo_auth":false,"s21c08_exclusion_invalida":true,"s21c08_cambio_sin_revalidar":false},"esperado":false},{"casuistica":"Vector 4","entrada":{"s21c08_modulo_auth":false,"s21c08_exclusion_invalida":true,"s21c08_cambio_sin_revalidar":true},"esperado":false},{"casuistica":"Vector 5","entrada":{"s21c08_modulo_auth":true,"s21c08_exclusion_invalida":false,"s21c08_cambio_sin_revalidar":false},"esperado":false},{"casuistica":"Vector 6","entrada":{"s21c08_modulo_auth":true,"s21c08_exclusion_invalida":false,"s21c08_cambio_sin_revalidar":true},"esperado":true},{"casuistica":"Vector 7","entrada":{"s21c08_modulo_auth":true,"s21c08_exclusion_invalida":true,"s21c08_cambio_sin_revalidar":false},"esperado":true},{"casuistica":"Vector 8","entrada":{"s21c08_modulo_auth":true,"s21c08_exclusion_invalida":true,"s21c08_cambio_sin_revalidar":true},"esperado":true}]},"codigo":"S21-C08","hash":"e4ce5420b2d0f413fe52e24850d5ba2d3df79ac18826e9c378a9db616a902575","hash_paquete":"61d6d2ca5f3eccf99153e5ae33d7ebb45edfbca0bc91af7fadbe7fa99db68e8e","hash_evaluado":"e4ce5420b2","hash_paquete_10":"61d6d2ca5f","puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":0.9,"observacion":"No duplicar la exclusión FEATURE_FLAGS/I18N de IG."},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"diferencias":"Exclusión funcional explícita y revalidación por cambio de alcance; no modifica IG."}]$pack$::jsonb;
p jsonb; a jsonb; ans jsonb; val jsonb; h text; cd text; lid int; residual text; diff text; old_desc text; n int:=0; links int:=0; vectors int:=0; t record; b_leg jsonb; b_dep jsonb; b_cfg jsonb;
BEGIN
SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S21_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S21_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR ans->>'hash_paquete' IS DISTINCT FROM h OR left(p->>'hash',10) IS DISTINCT FROM p->>'hash_evaluado' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S21_ATTESTATION_DRIFT %',cd; END IF;
 IF (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1)<>8 THEN RAISE EXCEPTION 'S21_VECTOR_COUNT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S21_VECTOR_FAIL % %',cd,t.entrada; END IF;
 vectors:=vectors+1;
 END LOOP;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto','PASS','puntajes',p->'puntajes','juez','Claude','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','PR #4752 / Claude 2026-11-24 19:05 Lima / '||cd||' / '||(p->>'hash_evaluado'));
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S21_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision' IS DISTINCT FROM 'AUTO' THEN RAISE EXCEPTION 'S21_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado' IS DISTINCT FROM 'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S21_PROMOTION_FAIL % %',cd,ans; END IF;
 n:=n+1;
END LOOP;
IF n<>8 OR vectors<>64 THEN RAISE EXCEPTION 'S21_PUBLICATION_INCOMPLETE'; END IF;
FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legacy_id')::int; h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 residual:=p->>'residual'; diff:=p->>'diferencias';
 IF h IS DISTINCT FROM p->>'hash_paquete' OR length(diff)>4000 OR (lid=44 AND length(residual)<15) OR (lid<>44 AND residual IS DISTINCT FROM '') THEN RAISE EXCEPTION 'S21_COVERAGE_CONTRACT %',cd; END IF;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 VALUES(lid,cd,1,CASE WHEN lid=44 THEN 'PARCIAL' ELSE 'REEMPLAZADA' END,diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||(p->'paquete'->>'descripcion')||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente S21 2026-11-24 19:05','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),h,'GPT / Claude S21 independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S21_SOURCE_MISSING %',lid; END IF;
END LOOP;
IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND links<>8) OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S21_INVARIANT_FAIL'; END IF;
IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S21_DPIG03_FAIL'; END IF;
RAISE NOTICE 'S21_PASS 8 JUICIOS 8 AUTO 64 VECTORES links=% DPIG03=0',links;
END $s21$;
COMMIT;
